-- Model: gemini-embedding-001 — outputs 3072 dims for high fidelity
--        (Optimized for v1beta with full semantic density)
-- =============================================================

-- Enable pgvector extension
create extension if not exists vector;

-- 1. NUCLEAR CLEANUP — drop ALL match_documents functions (any dimension)
DO $$ 
DECLARE 
  r RECORD;
BEGIN 
  FOR r IN (
    SELECT oid::regprocedure AS func_signature
    FROM pg_proc 
    WHERE proname = 'match_documents'
  ) 
  LOOP 
    EXECUTE 'DROP FUNCTION IF EXISTS ' || r.func_signature || ' CASCADE'; 
  END LOOP; 
END $$;

-- Drop old table
DROP TABLE IF EXISTS documents CASCADE;

-- 2. Create Table — 3072 dimensions
create table documents (
  id uuid primary key default gen_random_uuid(),
  content text not null,
  metadata jsonb default '{}'::jsonb,
  -- Change vector to halfvec
  embedding halfvec(3072), 
  created_at timestamptz default now()
);

-- HNSW index — recommended for high-dimensional vectors (like 3072)
create index on documents 
using hnsw (embedding halfvec_cosine_ops);

-- 3. match_documents function — 3072 dimensions
create or replace function match_documents (
  query_embedding halfvec(3072),
  match_threshold float,
  match_count int
)
returns table (
  id uuid,
  content text,
  metadata jsonb,
  similarity float
)
language plpgsql
as $$
begin
  return query
  select
    documents.id,
    documents.content,
    documents.metadata,
    1 - (documents.embedding <=> query_embedding) as similarity
  from documents
  where 1 - (documents.embedding <=> query_embedding) > match_threshold
  order by documents.embedding <=> query_embedding
  limit match_count;
end;
$$;

